export class ParseError extends Error {}
const fail = (m) => { throw new ParseError(m) }

class Table { constructor() { this.map = new Map(); this.defined = false } }
class Arr { constructor(aot) { this.items = []; this.aot = aot } }
class Scalar { constructor(type, value) { this.type = type; this.value = value } }

const INT = /^[+-]?\d+(_\d+)*$/
const FLOAT = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/
const isWs = (c) => c === ' ' || c === '\t'
const isNameCh = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)

function walk(table, parts, path, upto) {
  let t = table
  for (let i = 0; i < upto; i++) {
    path.push(parts[i])
    let n = t.map.get(parts[i])
    if (n === undefined) { n = new Table(); t.map.set(parts[i], n) }
    if (n instanceof Arr && n.aot) n = n.items[n.items.length - 1]
    if (!(n instanceof Table)) fail(`${path.join('.')} is not a table`)
    t = n
  }
  return t
}

class LineParser {
  constructor(s) { this.s = s; this.i = 0 }
  peek() { return this.s[this.i] }
  ws() { while (isWs(this.s[this.i])) this.i++ }
  atEnd() { this.ws(); const c = this.peek(); return c === undefined || c === '#' || c === ';' }

  string(q) {
    this.i++
    let out = ''
    for (;;) {
      const c = this.s[this.i]
      if (c === undefined) fail('unterminated string')
      if (c === q) { this.i++; return out }
      if (q === '"' && c === '\\') {
        const e = this.s[this.i + 1]
        if (e === undefined) fail('unterminated string')
        const m = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
        if (Object.hasOwn(m, e)) { out += m[e]; this.i += 2; continue }
        if (e === 'u') {
          const h = this.s.slice(this.i + 2, this.i + 6)
          if (!/^[0-9a-fA-F]{4}$/.test(h)) fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16)); this.i += 6; continue
        }
        fail(`invalid escape \\${e}`)
      }
      out += c; this.i++
    }
  }

  name() {
    const c = this.peek()
    if (c === '"' || c === "'") return this.string(c)
    const st = this.i
    while (isNameCh(this.s[this.i])) this.i++
    if (this.i === st) fail('expected a name')
    return this.s.slice(st, this.i)
  }

  dotted() {
    const parts = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.peek() === '.') { this.i++; this.ws(); parts.push(this.name()) } else { this.i = save; return parts }
    }
  }

  assign(table, base, parts, value) {
    const path = [...base]
    const t = walk(table, parts, path, parts.length - 1)
    const last = parts[parts.length - 1]
    path.push(last)
    if (t.map.has(last)) fail(`key ${path.join('.')} is defined twice`)
    t.map.set(last, value)
  }

  value() {
    this.ws()
    const c = this.peek()
    if (c === '"' || c === "'") return new Scalar('string', this.string(c))
    if (c === '[') return this.array()
    if (c === '{') return this.inline()
    const st = this.i
    while (this.i < this.s.length && !isWs(this.s[this.i]) && !',]};'.includes(this.s[this.i])) this.i++
    const w = this.s.slice(st, this.i)
    if (w === '') fail('expected a value')
    if (w === 'true') return new Scalar('boolean', true)
    if (w === 'false') return new Scalar('boolean', false)
    if (INT.test(w)) return new Scalar('integer', Number(w.replaceAll('_', '')))
    if (FLOAT.test(w)) return new Scalar('float', Number(w.replaceAll('_', '')))
    fail(`invalid value ${w}`)
  }

  array() {
    this.i++
    const a = new Arr(false)
    for (;;) {
      this.ws()
      if (this.peek() === ']') { this.i++; return a }
      a.items.push(this.value())
      this.ws()
      const c = this.peek()
      if (c === ',') this.i++
      else if (c === ']') { this.i++; return a }
      else fail('unterminated array')
    }
  }

  inline() {
    this.i++
    const t = new Table()
    t.defined = true
    this.ws()
    if (this.peek() === '}') { this.i++; return t }
    for (;;) {
      this.ws()
      const parts = this.dotted()
      this.ws()
      if (this.peek() !== '=') fail('expected = in an inline table')
      this.i++
      const v = this.value()
      this.assign(t, [], parts, v)
      this.ws()
      const c = this.peek()
      if (c === ',') this.i++
      else if (c === '}') { this.i++; return t }
      else fail('unterminated inline table')
    }
  }

  header(root) {
    this.i++
    const aot = this.peek() === '['
    if (aot) this.i++
    this.ws()
    const parts = this.dotted()
    this.ws()
    const close = aot ? ']]' : ']'
    if (this.s.slice(this.i, this.i + close.length) !== close) fail('unterminated table header')
    this.i += close.length
    if (!this.atEnd()) fail('trailing text after a table header')
    const path = []
    const t = walk(root, parts, path, parts.length - 1)
    const last = parts[parts.length - 1]
    path.push(last)
    const p = path.join('.')
    let n = t.map.get(last)
    if (aot) {
      if (n === undefined) { n = new Arr(true); t.map.set(last, n) }
      if (!(n instanceof Arr && n.aot)) fail(`${p} is not an array of tables`)
      const nt = new Table(); nt.defined = true
      n.items.push(nt)
      return { table: nt, path }
    }
    if (n === undefined) { n = new Table(); t.map.set(last, n) }
    if (!(n instanceof Table)) fail(`${p} is not a table`)
    if (n.defined) fail(`table ${p} is defined twice`)
    n.defined = true
    return { table: n, path }
  }
}

export function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = new Table()
  let cur = { table: root, path: [] }
  lines.forEach((line, idx) => {
    try {
      const p = new LineParser(line)
      p.ws()
      const c = p.peek()
      if (c === undefined || c === '#' || c === ';') return
      if (c === '[') { cur = p.header(root); return }
      const parts = p.dotted()
      p.ws()
      if (p.peek() !== '=') fail('expected key = value')
      p.i++
      const v = p.value()
      if (!p.atEnd()) fail('trailing text after a value')
      p.assign(cur.table, cur.path, parts, v)
    } catch (e) {
      if (e instanceof ParseError) e.message = `line ${idx + 1}: ${e.message}`
      throw e
    }
  })
  return root
}

const cmp = (a, b) => {
  const x = [...a], y = [...b]
  for (let i = 0; i < Math.min(x.length, y.length); i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
const sortedKeys = (t) => [...t.map.keys()].sort(cmp)

export function toJson(n, ind = '') {
  const in2 = ind + '  '
  if (n instanceof Scalar) return JSON.stringify(n.value)
  if (n instanceof Arr) {
    if (!n.items.length) return '[]'
    return '[\n' + n.items.map((x) => in2 + toJson(x, in2)).join(',\n') + '\n' + ind + ']'
  }
  const ks = sortedKeys(n)
  if (!ks.length) return '{}'
  return '{\n' + ks.map((k) => `${in2}${JSON.stringify(k)}: ${toJson(n.map.get(k), in2)}`).join(',\n') + '\n' + ind + '}'
}

export function toKeys(n, prefix = '', out = []) {
  const line = (path, x) => {
    out.push(`${path} ${x instanceof Scalar ? x.type : x instanceof Arr ? 'array' : 'table'}`)
    toKeys(x, path, out)
  }
  if (n instanceof Arr) n.items.forEach((x, i) => line(`${prefix}[${i}]`, x))
  else if (n instanceof Table) for (const k of sortedKeys(n)) line(prefix === '' && true ? k : `${prefix}.${k}`, n.map.get(k))
  return out
}
